-- Four ready-made templates that use the newer question types and the logic engine
-- (NPS, rating, slider, ranking, yes/no, number; branching on scores). Additive:
-- the 15 existing templates are untouched. Idempotent by template name.
insert into public.survey_templates (organization_id, name, description, category, definition, default_privacy_mode, is_active, created_by)
select null, v.name, v.description, v.category, v.definition, v.mode::survey_privacy_mode, true, 'Aspire starter templates'
from (values
  ('Customer Experience Suite (NPS, CSAT, CES)', 'The three customer metrics in one short survey: Net Promoter Score, satisfaction (CSAT) and effort (CES), with a follow-up that appears only for unhappy customers. One open link, no identity involved. ~3 minutes.', 'Customer Experience', '{"slug":"customer-experience-suite","title":"Customer Experience Survey","welcome":{"heading":"Welcome","body":["This survey takes about 3 minutes to complete.","There are no right or wrong answers - please answer as honestly as you can."],"startLabel":"Begin Survey"},"thankYou":{"heading":"Thank you","body":"Your response has been recorded. Thank you for taking the time to share your feedback."},"sections":[{"id":"scores","title":"Your experience","questions":[{"id":"nps","type":"nps","label":"How likely are you to recommend us to a friend or colleague?","required":true,"lowLabel":"Not at all likely","highLabel":"Extremely likely"},{"id":"csat","type":"rating","label":"How satisfied were you with your most recent experience?","required":true,"max":5,"shape":"star"},{"id":"ces","type":"rating","label":"How easy was it to get what you needed?","required":true,"max":7,"shape":"number","lowLabel":"Very difficult","highLabel":"Very easy"},{"id":"why_low","type":"textarea","label":"We are sorry it was not better. What went wrong?","required":false,"maxLength":800,"showIf":{"match":"any","rules":[{"questionId":"nps","op":"lte","value":["6"]},{"questionId":"csat","op":"lte","value":["2"]}]}},{"id":"why_high","type":"textarea","label":"What did we do best?","required":false,"maxLength":800,"showIf":{"questionId":"nps","equals":["9","10"]}}]},{"id":"improve","title":"What to improve","questions":[{"id":"priorities","type":"ranking","label":"Rank what we should improve first.","required":false,"randomize":true,"options":["Speed","Price","Quality","Support","Range"]}]}]}'::jsonb, 'ANONYMOUS'),
  ('eNPS Pulse with Follow-up Logic', 'A short employee pulse built around eNPS. Follow-up questions branch on the score: detractors are asked what is wrong, people thinking of leaving are asked why and what would help, and promoters skip straight to the end. ~4 minutes.', 'Engagement', '{"slug":"enps-pulse-logic","title":"Employee Pulse","welcome":{"heading":"Welcome","body":["This survey takes about 4 minutes to complete.","There are no right or wrong answers - please answer as honestly as you can."],"startLabel":"Begin Survey"},"thankYou":{"heading":"Thank you","body":"Your response has been recorded. Thank you for taking the time to share your feedback."},"sections":[{"id":"pulse","title":"How are things?","questions":[{"id":"enps","type":"nps","label":"How likely are you to recommend working here to a friend?","required":true,"lowLabel":"Not at all likely","highLabel":"Extremely likely"},{"id":"manager_support","type":"rating","label":"How supported do you feel by your manager?","required":true,"max":5,"shape":"star"},{"id":"workload","type":"slider","label":"How full is your workload right now?","required":false,"min":0,"max":100,"step":5,"unit":"%","lowLabel":"Far too light","highLabel":"Overwhelming"},{"id":"engagement_items","type":"matrix","label":"How much do you agree with each statement?","required":true,"rows":["I am proud to work here","I have the tools I need","I get useful feedback"],"scale":["Strongly disagree","Disagree","Neutral","Agree","Strongly agree"],"columnPrefix":"engagement_items"}],"jumps":[{"when":{"questionId":"enps","equals":["9","10"]},"to":"closing"}]},{"id":"retention","title":"Your future here","questions":[{"id":"enps_why","type":"textarea","label":"You gave us a {{answer:enps}}. What is the main reason?","required":false,"maxLength":600},{"id":"considering_leaving","type":"yesno","label":"Have you thought about leaving in the last three months?","required":true},{"id":"leave_reasons","type":"checkbox","label":"What are the main reasons?","required":true,"randomize":true,"maxSelections":3,"options":["Pay","Career growth","My manager","Workload","Culture","Other"],"otherColumn":"leave_reasons_other","showIf":{"questionId":"considering_leaving","equals":["Yes"]}},{"id":"retention_offer","type":"radio","label":"What would most help you stay?","required":false,"options":["A pay review","A clearer career path","A change of team","More flexibility","Nothing would change my mind"],"showIf":{"questionId":"considering_leaving","equals":["Yes"]}}]},{"id":"closing","title":"Anything else?","questions":[{"id":"comment","type":"textarea","label":"Is there anything else you would like leadership to hear?","required":false,"maxLength":800}]}]}'::jsonb, 'CONFIDENTIAL'),
  ('Event or Workshop Feedback', 'Quick feedback after an event, workshop or webinar: overall rating, whether it met expectations, the most and least useful parts, and a recommend score. ~3 minutes.', 'Training', '{"slug":"event-feedback","title":"Event Feedback","welcome":{"heading":"Welcome","body":["This survey takes about 3 minutes to complete.","There are no right or wrong answers - please answer as honestly as you can."],"startLabel":"Begin Survey"},"thankYou":{"heading":"Thank you","body":"Your response has been recorded. Thank you for taking the time to share your feedback."},"sections":[{"id":"overall","title":"Overall","questions":[{"id":"rating","type":"rating","label":"Overall, how would you rate the event?","required":true,"max":5,"shape":"star"},{"id":"expectations","type":"radio","label":"Did it meet your expectations?","required":true,"options":["Exceeded them","Met them","Partly met them","Did not meet them"]},{"id":"recommend","type":"nps","label":"How likely are you to recommend this to a colleague?","required":true,"lowLabel":"Not at all likely","highLabel":"Extremely likely"}]},{"id":"content","title":"The content","questions":[{"id":"most_useful","type":"ranking","label":"Rank the parts of the event from most to least useful.","required":true,"randomize":true,"options":["Keynote","Hands-on session","Q&A","Networking","Materials"]},{"id":"pace","type":"slider","label":"How was the pace?","required":false,"min":0,"max":10,"step":1,"lowLabel":"Far too slow","highLabel":"Far too fast"},{"id":"attend_again","type":"yesno","label":"Would you attend a follow-up event?","required":true},{"id":"suggestions","type":"textarea","label":"What one thing would you change?","required":false,"maxLength":600}]}]}'::jsonb, 'ANONYMOUS'),
  ('Training Needs Analysis', 'Finds out where to invest in learning: current confidence by skill area, the skills people most want to build (ranked), preferred learning formats and time available. ~6 minutes.', 'Training', '{"slug":"training-needs-analysis","title":"Training Needs Analysis","welcome":{"heading":"Welcome","body":["This survey takes about 6 minutes to complete.","There are no right or wrong answers - please answer as honestly as you can."],"startLabel":"Begin Survey"},"thankYou":{"heading":"Thank you","body":"Your response has been recorded. Thank you for taking the time to share your feedback."},"sections":[{"id":"skills","title":"Your skills","questions":[{"id":"confidence","type":"matrix","label":"How confident are you in each area today?","required":true,"rows":["Data and analysis","Communication","Leadership","Project management","Digital tools"],"scale":["Not at all confident","Slightly confident","Moderately confident","Very confident","Extremely confident"],"columnPrefix":"confidence"},{"id":"want_to_build","type":"ranking","label":"Rank the skills you most want to build.","required":true,"randomize":true,"options":["Data and analysis","Communication","Leadership","Project management","Digital tools"]}]},{"id":"how","title":"How you like to learn","questions":[{"id":"formats","type":"checkbox","label":"Which learning formats work best for you?","required":true,"randomize":true,"options":["Workshop","Self-paced online","Coaching or mentoring","On the job","Reading","None of the above"]},{"id":"hours","type":"number","label":"How many hours a month could you realistically spend learning?","required":true,"min":0,"max":100,"unit":"hours"},{"id":"blockers","type":"textarea","label":"What most gets in the way of learning at work?","required":false,"maxLength":600}]}]}'::jsonb, 'ANONYMOUS_TRACKED')
) as v(name, description, category, definition, mode)
where not exists (select 1 from public.survey_templates x where x.organization_id is null and x.name = v.name);
